// Set a default page number if not already set
if (!pm.environment.get("pageNumber")) {
    pm.environment.set("pageNumber", "1");
}

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Content-Type is application/json", function () {
    pm.response.to.have.header("Content-Type", "application/json; charset=utf-8");
});


pm.test("Response time is less than 200ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(200);
});


let responseJson = pm.response.json();

pm.test("Page number is correct", function() {
    pm.expect(responseJson.page).to.eql(parseInt(pm.environment.get("pageNumber")));
});

pm.test("Data array is present and not empty", function() {
    pm.expect(responseJson.data).to.be.an('array').that.is.not.empty;
});

pm.test("Each user object has required properties", function() {
    responseJson.data.forEach(user => {
        pm.expect(user).to.have.property('id');
        pm.expect(user).to.have.property('email');
        pm.expect(user).to.have.property('first_name');
        pm.expect(user).to.have.property('last_name');
        pm.expect(user).to.have.property('avatar');
    });
});

pm.test("Valid email format", function() {
    responseJson.data.forEach(user => {
        pm.expect(user.email).to.match(/^[^@\s]+@[^@\s]+\.[^@\s]+$/);
    });
});


pm.test("Support object is present and has required properties", function() {
    pm.expect(responseJson.support).to.be.an('object');
    pm.expect(responseJson.support).to.have.property('url');
    pm.expect(responseJson.support).to.have.property('text');
});

pm.test("Valid URL format for avatar", function() {
    responseJson.data.forEach(user => {
        pm.expect(user.avatar).to.match(/^(ftp|http|https):\/\/[^ "]+$/);
    });
});

pm.test("Valid URL format for support url", function() {
    pm.expect(responseJson.support.url).to.match(/^(ftp|http|https):\/\/[^ "]+$/);
});

